import sys
from collections import Counter

# Map A-Z to a-z, a-z to a-z, and everything else to space (0x20)
_TRANS = bytes(
    b + 32 if 65 <= b <= 90 else (b if 97 <= b <= 122 else 32)
    for b in range(256)
)

def main():
    data = sys.stdin.buffer.read()
    if not data:
        return
    words = data.translate(_TRANS).split()
    counts = Counter(words)
    # Sort by (-count, word) to break ties alphabetically by word
    top10 = sorted(counts.items(), key=lambda kv: (-kv[1], kv[0]))[:10]
    out = "\n".join(f"{w.decode('ascii')} {c}" for w, c in top10)
    if out:
        sys.stdout.write(out + "\n")

if __name__ == "__main__":
    main()
